structure.mermaidSource:
flowchart TD
  start["Início: Segmento Textual Sob Análise"] --> dec_1{"O segmento relata fatos encadeados e conta uma história no tempo?"}
  dec_1 -- "Sim (Fatos / Sucessão temporal)" --> res_narracao["Confirmação Plena: Tipologia NARRATIVA"]
  dec_1 -- "Não (Sem sucessão temporal)" --> dec_2{"O segmento qualifica seres/cenários e detalha atributos em simultaneidade?"}
  dec_2 -- "Sim (Qualifica / Detalha atributos)" --> res_descricao["Confirmação Plena: Tipologia DESCRIÇÃO"]
  dec_2 -- "Não (Conceitual / Instrucional)" --> res_outra["Classificação Residual: Outra Base Tipológica (Dissertação / Injunção)"]

flowchart TD
  start["Início: Item da Banca e Texto Híbrido"] --> dec_tipo_prop{"Qual o tipo de proposição da banca?"}
  dec_tipo_prop -- "Cumulativa (coexistência)" --> dec_coexist{"Texto combina sequências narrativas e descritivas?"}
  dec_coexist -- "Sim" --> res_cumulativo_certo["Gabarito: CERTO (Reconhece o hibridismo legítimo)"]
  dec_coexist -- "Não" --> res_cumulativo_errado["Gabarito: ERRADO (Tipologias não coincidem com o item)"]
  dec_tipo_prop -- "Excludente (predomínio absoluto)" --> proc_inspecao["Passo 2: Inspeção Tripartite (Abertura, Meio e Desfecho)"]
  proc_inspecao --> dec_enredo{"Enredo avança no tempo (abertura com ação e desfecho conclusivo)?"}
  dec_enredo -- "Sim (Enredo cronológico ativo)" --> proc_diag_narr["Diagnóstico: Predominantemente Narrativo (descrição é acessória)"]
  dec_enredo -- "Não (Sem progressão temporal)" --> proc_diag_desc["Diagnóstico: Predominantemente Descritivo (estados estáticos)"]
  proc_diag_narr --> dec_afirm_narr{"O que afirma a assertiva excludente?"}
  dec_afirm_narr -- "Predominantemente Narrativo" --> res_excl_narr_certo["Gabarito: CERTO (Predomínio narrativo confirmado)"]
  dec_afirm_narr -- "Predominantemente Descritivo" --> res_excl_desc_errado["Gabarito: ERRADO (Descrição é mero suporte ao enredo)"]
  proc_diag_desc --> dec_afirm_desc{"O que afirma a assertiva excludente?"}
  dec_afirm_desc -- "Predominantemente Descritivo" --> res_excl_desc_certo["Gabarito: CERTO (Predomínio descritivo confirmado)"]
  dec_afirm_desc -- "Predominantemente Narrativo" --> res_excl_narr_errado["Gabarito: ERRADO (Ausência de sucessão temporal de ações)"]
